export const SHOP_ALL: ShopProduct[] = [...SHOP_KIDS, ...SHOP_DATABASES];

export function shopProductJsonLd(p: ShopProduct) {
  return {
    "@type": "Product",
    name: p.title,
    description: p.hook,
    image: p.img,
    offers: {
      "@type": "Offer",
      price: p.priceValue,
      priceCurrency: "USD",
      availability: "https://schema.org/InStock",
      url: p.href,
    },
  };
}

function ProductCard({ p }: { p: ShopProduct }) {
  return (
    <a
      id={p.id}
      href={p.href}
      target="_blank"
      rel="noopener noreferrer"
      className="shop-card"
      aria-label={`${p.title} — ${p.price} on Gumroad`}
    >
      <div
        className={`shop-card__img ${p.portrait ? "shop-card__img--portrait" : "shop-card__img--landscape"}`}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={p.img} alt={p.alt} loading="lazy" decoding="async" />
      </div>
      <div className="shop-card__body">
        <h3 className="shop-card__title">{p.title}</h3>
        <p className="shop-card__hook">{p.hook}</p>
        <ul className="shop-card__bullets">
          {p.bullets.map((b) => (
            <li key={b}>{b}</li>
          ))}
        </ul>
        <p className="shop-card__badges">{p.badges}</p>
        <div className="shop-card__foot">
          <span className="shop-card__price">{p.price}</span>
          <span className="shop-card__cta">{p.cta}</span>
        </div>
      </div>
    </a>
  );
}

